// ── Demo: granny vs square (reef) knot ────────────────────────────────
// Two ropes tied with two crossings. The only difference between the knots is
// the handedness of the SECOND crossing: opposite to the first gives a square
// (reef) knot that seats flat and holds; the same as the first gives a granny
// that capsizes and slips. Toggle the handedness, then pull the ends: the
// square cinches and locks, the granny slides apart.
(function(){
  var c = document.getElementById('knotCanvas'); if (!c) return;
  var ctx = c.getContext('2d');
  var btn = document.getElementById('knotToggle'), verdict = document.getElementById('knotVerdict');
  var pull = document.getElementById('knotPull');
  var W = c.width, H = c.height, topY = H * 0.36, botY = H * 0.64;
  // Retina-crisp: scale the backing store by devicePixelRatio (capped 2x, matching
  // pretext.html) and the context to match, so all drawing stays in logical W/H.
  // Without it the fixed 560x200 bitmap is upscaled by CSS and reads soft.
  var DPR = Math.min(window.devicePixelRatio || 1, 2);
  c.width = W * DPR; c.height = H * DPR; ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  var square = true, t = 0, anim = 0; // t: pull progress 0..1
  var RED = '#b03a4a', BLUE = '#2f6fd0';
  function ss(a, b, u) { u = u < 0 ? 0 : u > 1 ? 1 : u; u = u * u * (3 - 2 * u); return a + (b - a) * u; }
  function crossings() {
    // pull cinches the two crossings; a granny also slides them apart (slipping)
    if (square) return [ss(0.34, 0.44, t), ss(0.66, 0.56, t)];
    return [ss(0.34, 0.16, t), ss(0.66, 0.84, t)];
  }
  function yOf(which, x, c1, c2) {
    var sw = 0.06, lane = which === 'A' ? [topY, botY] : [botY, topY];
    if (x < c1 - sw) return lane[0];
    if (x < c1 + sw) return ss(lane[0], lane[1], (x - (c1 - sw)) / (2 * sw));
    if (x < c2 - sw) return lane[1];
    if (x < c2 + sw) return ss(lane[1], lane[0], (x - (c2 - sw)) / (2 * sw));
    return lane[0];
  }
  function path(which, c1, c2) {
    ctx.beginPath();
    for (var i = 0; i <= 200; i++) { var x = i / 200, X = 16 + x * (W - 32), Y = yOf(which, x, c1, c2); i ? ctx.lineTo(X, Y) : ctx.moveTo(X, Y); }
  }
  function overSeg(which, xc, c1, c2) {
    // redraw a short segment of `which` over the crossing, with a background gap under it
    ctx.lineWidth = 11; ctx.strokeStyle = '#fffafa'; ctx.beginPath();
    for (var i = -10; i <= 10; i++) { var x = xc + i / 200, X = 16 + x * (W - 32), Y = yOf(which, x, c1, c2); i === -10 ? ctx.moveTo(X, Y) : ctx.lineTo(X, Y); }
    ctx.stroke();
    ctx.lineWidth = 7; ctx.strokeStyle = which === 'A' ? RED : BLUE; ctx.beginPath();
    for (var j = -10; j <= 10; j++) { var x2 = xc + j / 200, X2 = 16 + x2 * (W - 32), Y2 = yOf(which, x2, c1, c2); j === -10 ? ctx.moveTo(X2, Y2) : ctx.lineTo(X2, Y2); }
    ctx.stroke();
  }
  function draw() {
    var cr = crossings(), c1 = cr[0], c2 = cr[1];
    ctx.clearRect(0, 0, W, H); ctx.lineCap = 'round'; ctx.lineWidth = 7;
    ctx.strokeStyle = RED; path('A', c1, c2); ctx.stroke();
    ctx.strokeStyle = BLUE; path('B', c1, c2); ctx.stroke();
    overSeg('A', c1, c1, c2);                       // crossing 1: A over (fixed)
    overSeg(square ? 'B' : 'A', c2, c1, c2);        // crossing 2: opposite (square) or same (granny)
    if (btn) btn.textContent = square ? 'knot: square (reef)' : 'knot: granny';
    if (verdict) verdict.innerHTML = square
      ? '<b>Square (reef).</b> The second crossing mirrors the first, so the knot seats flat and each rope nips the other. Pull and it locks.'
      : '<b>Granny.</b> The second crossing repeats the first, so the knot is unbalanced. Pull and it capsizes and slides apart, a slip waiting to happen.';
  }
  function loop() { if (t < 1) { t = Math.min(1, t + 0.03); draw(); anim = requestAnimationFrame(loop); } }
  function startPull() { if (anim) cancelAnimationFrame(anim); t = 0; draw(); anim = requestAnimationFrame(loop); }
  if (btn) btn.addEventListener('click', function () { square = !square; t = 0; draw(); });
  if (pull) pull.addEventListener('click', startPull);
  draw();
})();
